                const data = {
                    lat: position.coords.latitude,
                    lng: position.coords.longitude,
                    timestamp: position.timestamp
                };
                sendToServer(data);
            },
            (error) => console.error("Error:", error),
            {
                enableHighAccuracy: true, // Uses GPS instead of just Wi-Fi/Cell towers
                maximumAge: 0,
                timeout: 5000
            }
