    print("Access Granted")
```

#### C (Low-level implementation)
If you are working in an embedded system or writing a crypto library, you must ensure the compiler doesn't "optimize" your constant-time loop back into a fast-exit loop.

```c
#include <stdint.h>
#include <stddef.h>

int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        // XOR returns 0 if bits are identical, non-zero otherwise
        // ORing into 'result' ensures that if any byte differs, 
        // 'result' will become non-zero and stay non-zero.
        result |= (a[i] ^ b[i]);
    }

    // Return 1 if equal, 0 if not.
    // We use a double negation to turn any non-zero value into 1
    return (result == 0);
}
