const int SENSOR_PIN = A0;      // Pin connected to EMI sensor
const int SAMPLE_SIZE = 10;     // Number of samples for smoothing
int readings[SAMPLE_SIZE];      // Array for moving average
int readIndex = 0;
long total = 0;
int average = 0;

void setup() {
  Serial.begin(115200);
  for (int i = 0; i < SAMPLE_SIZE; i++) readings[i] = 0;
}

void loop() {
  // Subtract the last reading
  total = total - readings[readIndex];

  // Read from sensor (0 - 1023)
  readings[readIndex] = analogRead(SENSOR_PIN);

  // Add new reading to total
  total = total + readings[readIndex];
  readIndex = (readIndex + 1) % SAMPLE_SIZE;

  // Calculate average
  average = total / SAMPLE_SIZE;

  // Output format: [TIMESTAMP_MS, RAW_VALUE, SMOOTHED_VALUE]
  Serial.print(millis());
  Serial.print(",");
  Serial.print(analogRead(SENSOR_PIN));
  Serial.print(",");
  Serial.println(average);

  delay(100); // Sample at 10Hz
}
